SELECT game_id AS "gameId", step_id AS "stepId", sequence_id AS "sequenceId", step_order AS "stepOrder", operation_type_id AS "operationTypeId", target_selector_type_id AS "targetSelectorTypeId", condition_formula_key AS "conditionFormulaKey", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.effect_steps WHERE game_id = #{gameId}
AND sequence_id = #{sequenceId}
ORDER BY sequence_id, step_order
